  35: struct PasswordGenerator {
  36:     charset: Vec<u8>,
  37:     // Direct lookup table: byte value -> index in charset (avoids HashMap hashing)
  38:     charset_lookup: [u8; 128],
  39:     charset_len: usize,
  40:     charset_last_idx: u8,
  41:     max_size: usize,
  42:     generated_count: usize,
  43:     total_to_generate: usize,
  44:     password: Vec<u8>,
  45:     progress_bar: ProgressBar,
  46: }
  47: 
  48: impl PasswordGenerator {
  49:     fn new(
  50:         charset: Vec<char>,
  51:         min_size: usize,
  52:         max_size: usize,
  53:         starting_password: Option<String>,
  54:         progress_bar: ProgressBar,
  55:     ) -> Self {
  56:         let charset_bytes: Vec<u8> = charset.iter().map(|&c| c as u8).collect();
  57:         let charset_len = charset_bytes.len();
  58: 
  59:         // Build direct lookup table: byte -> index in charset
  60:         let mut charset_lookup = [0u8; 128];
  61:         for (i, &b) in charset_bytes.iter().enumerate() {
  62:             charset_lookup[b as usize] = i as u8;
  63:         }
  64: 
  65:         let charset_last_idx = (charset_len - 1) as u8;
  66: 
  67:         let mut password = vec![charset_bytes[0]; min_size];
  68:         let mut total_to_generate = password_generator_count(charset_len, min_size, max_size);
