 159:     max_size: usize,
 160:     starting_password: Option<String>,
 161:     progress_bar: ProgressBar,
 162: ) -> impl Iterator<Item = Vec<u8>> {
 163:     // start generation
 164:     if let Some(starting_password) = &starting_password {
 165:         progress_bar.println(format!(
 166:             "Generating passwords with length from {} to {} starting from {} for charset with length {}\n{}",
 167:             min_size,
